SELECT sample_item_id,sample_key,item_name,category_code,status_code,searchable_text,owner_reference,sort_order,version_no,created_at,updated_at FROM REF_CMN_SAMPLE_ITEM WHERE deleted_yn='N' AND (? IS NULL OR status_code=?) AND (? IS NULL OR LOWER(item_name||' '||category_code||' '||NVL(searchable_text,'')) LIKE '%'||LOWER(?)||'%') ORDER BY sort_order,sample_item_id OFFSET ? ROWS FETCH NEXT ? ROWS ONLY
